package com.magraoxx.eichattv;

import android.Manifest;
import android.app.Activity;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.os.Bundle;
import android.provider.Settings;
import android.speech.RecognitionListener;
import android.speech.RecognizerIntent;
import android.speech.SpeechRecognizer;
import android.speech.tts.TextToSpeech;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ProgressBar;
import android.widget.ScrollView;
import android.widget.TextView;
import java.util.ArrayList;
import java.util.Locale;

public class MainActivity extends Activity implements RecognitionListener {
 private static final int REQ_MIC=1001; private TextView status,setupState,micLevelText; private ProgressBar micMeter; private SpeechRecognizer recognizer; private TextToSpeech tts; private CommandEngine commandEngine; private OpenAiClient aiClient; private ChatGptAuth chatGptAuth; private boolean pendingListen,retryingNoMatch; private float peakRms=-20f;
 @Override protected void onCreate(Bundle b){super.onCreate(b);commandEngine=new CommandEngine(this);aiClient=new OpenAiClient(this);chatGptAuth=new ChatGptAuth(this);buildUi();initTts();initSpeechRecognizer();if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){status.setText("Etapa 1 de 3 — permita o uso do microfone para continuar.");requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);}else refreshSetupState();if(getIntent()!=null&&getIntent().getBooleanExtra("start_listening",false))startListening();}
 @Override protected void onResume(){super.onResume();if(setupState!=null)refreshSetupState();}
 private void buildUi(){ScrollView s=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(48,24,48,48);s.addView(r);TextView t=new TextView(this);t.setText("Ei Chat TV — Teste 04");t.setTextSize(34);r.addView(t);TextView sub=new TextView(this);sub.setText("Configuração e diagnóstico");sub.setTextSize(20);r.addView(sub);setupState=new TextView(this);setupState.setTextSize(18);setupState.setPadding(0,10,0,10);r.addView(setupState);status=new TextView(this);status.setTextSize(18);status.setText("Preparando…");status.setPadding(0,0,0,10);r.addView(status);micLevelText=new TextView(this);micLevelText.setTextSize(18);micLevelText.setText("Nível do microfone: aguardando teste");r.addView(micLevelText);micMeter=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);micMeter.setMax(100);micMeter.setProgress(0);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,28);mp.setMargins(0,4,0,12);micMeter.setLayoutParams(mp);r.addView(micMeter);r.addView(button("1. Permitir microfone",v->requestMic()));r.addView(button("2. Continuar com ChatGPT",v->connectChatGpt()));r.addView(button("3. Configurações de voz da TV",v->openVoiceSettings()));r.addView(button("TESTAR MICROFONE — fale perto do controle",v->startListening()));r.addView(button("Testar PlayStation 5 / HDMI",v->testPlayStation()));r.addView(button("Diagnóstico técnico",v->status.setText(Diagnostics.buildReport(this)+"\nChatGPT: "+chatGptAuth.accountLabel()+"\nPico do microfone: "+peakRms+" dB")));setContentView(s);}
 private Button button(String x,View.OnClickListener l){Button b=new Button(this);b.setText(x);b.setTextSize(19);b.setAllCaps(false);b.setFocusable(true);b.setMinHeight(68);b.setOnClickListener(l);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);b.setLayoutParams(p);return b;}
 private void requestMic(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED){status.setText("Microfone já está permitido ✓");refreshSetupState();}else requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);}
 private void refreshSetupState(){boolean mic=checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;boolean speech=SpeechRecognizer.isRecognitionAvailable(this);setupState.setText("Microfone: "+(mic?"✓ permitido":"✗ falta permitir")+"\nReconhecimento Android: "+(speech?"✓ disponível":"✗ indisponível")+"\nChatGPT: "+chatGptAuth.accountLabel());if(mic)status.setText("Microfone permitido. Use TESTAR MICROFONE e fale perto do controle.");}
 private void connectChatGpt(){status.setText("Abrindo o login oficial do ChatGPT…");chatGptAuth.signIn(new ChatGptAuth.Callback(){public void onSuccess(String m){runOnUiThread(()->{refreshSetupState();status.setText(m);speak(m);});}public void onError(String m){runOnUiThread(()->{status.setText(m);speak(m);});}});}
 private void initTts(){tts=new TextToSpeech(this,r->{if(r==TextToSpeech.SUCCESS){tts.setLanguage(new Locale("pt","BR"));tts.setSpeechRate(1.02f);}});}
 private void initSpeechRecognizer(){try{if(SpeechRecognizer.isRecognitionAvailable(this)){recognizer=SpeechRecognizer.createSpeechRecognizer(this);recognizer.setRecognitionListener(this);}}catch(Throwable t){recognizer=null;}}
 private Intent speechIntent(){Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"pt-BR");i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_PREFERENCE,"pt-BR");i.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);i.putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,5);i.putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_COMPLETE_SILENCE_LENGTH_MILLIS,1800L);i.putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_POSSIBLY_COMPLETE_SILENCE_LENGTH_MILLIS,1200L);return i;}
 private void startListening(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){pendingListen=true;requestMic();return;}if(recognizer==null){initSpeechRecognizer();if(recognizer==null){status.setText("Reconhecimento de voz indisponível. A TCL não forneceu um serviço SpeechRecognizer para este app.");return;}}try{recognizer.cancel();peakRms=-20f;micMeter.setProgress(0);micLevelText.setText("Nível do microfone: esperando áudio…");status.setText("🎤 MICROFONE ATIVO — fale perto do controle.");recognizer.startListening(speechIntent());}catch(Throwable t){status.setText("Não consegui abrir o microfone: "+t.getClass().getSimpleName()+" — "+String.valueOf(t.getMessage()));}}
 private void handleSpeech(String q){retryingNoMatch=false;CommandEngine.Result r=commandEngine.execute(q);if(r.handled){status.setText("Ouvi: “"+q+"”\n"+r.message);if(!r.success)speak(r.message);return;}status.setText("Ouvi: “"+q+"”\nConsultando o ChatGPT…");aiClient.ask(q,new OpenAiClient.Callback(){public void onSuccess(String x){runOnUiThread(()->{status.setText(x);speak(x);});}public void onError(String x){runOnUiThread(()->{status.setText(x);speak(x);});}});}
 private void openVoiceSettings(){try{startActivity(new Intent(Settings.ACTION_VOICE_INPUT_SETTINGS));}catch(Throwable t){try{startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(Throwable e){status.setText("A TCL não expôs as configurações de assistente/voz para este aplicativo.");}}}
 private void testPlayStation(){HdmiController.SwitchResult r=new HdmiController(this).switchToPlayStation();status.setText(r.message);if(!r.success)speak(r.message);}
 private void speak(String x){if(tts!=null&&x!=null&&!x.trim().isEmpty())tts.speak(x,TextToSpeech.QUEUE_FLUSH,null,"ei_chat_answer");}
 @Override public void onRequestPermissionsResult(int c,String[] p,int[] g){super.onRequestPermissionsResult(c,p,g);if(c==REQ_MIC){boolean ok=g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED;refreshSetupState();status.setText(ok?"Microfone liberado ✓\nPressione TESTAR MICROFONE e fale.":"Permissão do microfone negada pela TV.");if(ok&&pendingListen){pendingListen=false;startListening();}}}
 public void onReadyForSpeech(Bundle b){status.setText("🎤 OUVINDO — fale agora.");}public void onBeginningOfSpeech(){status.setText("🎤 Voz detectada — continue falando…");}
 public void onRmsChanged(float x){if(x>peakRms)peakRms=x;int level=Math.max(0,Math.min(100,Math.round((x+2f)*8f)));if(micMeter!=null)micMeter.setProgress(level);if(micLevelText!=null){String quality=level<8?"sem sinal / muito baixo":level<30?"baixo":level<65?"bom":"forte";micLevelText.setText("Nível do microfone: "+quality+" ("+Math.round(x)+" dB) — pico "+Math.round(peakRms)+" dB");}}
 public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){status.setText("Voz recebida. Entendendo…");}
 public void onError(int e){String msg;switch(e){case SpeechRecognizer.ERROR_NO_MATCH:msg="Código 7: áudio recebido, mas as palavras não foram reconhecidas. Veja a barra do microfone acima.";break;case SpeechRecognizer.ERROR_AUDIO:msg="Erro de áudio: a TCL não entregou o áudio corretamente.";break;case SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS:msg="Sem permissão para usar o microfone.";break;case SpeechRecognizer.ERROR_RECOGNIZER_BUSY:msg="Reconhecedor ocupado.";break;case SpeechRecognizer.ERROR_NETWORK:case SpeechRecognizer.ERROR_NETWORK_TIMEOUT:msg="Falha de rede no serviço de reconhecimento.";break;case SpeechRecognizer.ERROR_SPEECH_TIMEOUT:msg="Nenhuma voz foi detectada. Se a barra também ficou parada, teste o microfone do controle.";break;default:msg="Falha no reconhecimento de voz (código "+e+").";}status.setText(msg);if(e==SpeechRecognizer.ERROR_NO_MATCH&&!retryingNoMatch){retryingNoMatch=true;status.postDelayed(()->{status.setText("Tentando novamente… fale perto do controle.");startListening();},700);}else retryingNoMatch=false;}
 public void onResults(Bundle b){ArrayList<String> m=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(m==null||m.isEmpty()){status.setText("O áudio chegou, mas nenhuma palavra foi reconhecida.");return;}handleSpeech(m.get(0));}public void onPartialResults(Bundle b){ArrayList<String> m=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(m!=null&&!m.isEmpty())status.setText("🎤 Estou ouvindo: “"+m.get(0)+"”");}public void onEvent(int e,Bundle b){}
 @Override protected void onDestroy(){if(recognizer!=null)recognizer.destroy();if(tts!=null)tts.shutdown();super.onDestroy();}
}
